out.push("\n\n尝试改变最低价格，观察 Maximum Thumb 的 aria-valuemin 如何同步变化。\n\n### 6.5 JavaScript 核心实现\n\n下面是自定义 Thumb 的键盘与语义状态管理代码。\n\n```javascript\nconst state = {\n  min: 20,\n  max: 150,\n  lowerLimit: 0,\n  upperLimit: 200,\n  step: 1\n};\n\nconst minThumb = document.querySelector('[data-thumb=\"min\"]');\nconst maxThumb = document.querySelector('[data-thumb=\"max\"]');\n\nconst currency = new Intl.NumberFormat('en-US', {\n  style: 'currency',\n  currency: 'USD'\n});\n\nfunction setPrice(type, value) {\n  if (type === 'min') {\n    state.min = Math.max(\n      state.lowerLimit,\n      Math.min(value, state.max)\n    );\n  } else {\n    state.max = Math.min(\n      state.upperLimit,\n      Math.max(value, state.min)\n    );\n  }\n\n  render();\n}\n\nfunction render() {\n  minThumb.setAttribute(\n    'aria-valuemin', state.lowerLimit\n  );\n\n  minThumb.setAttribute(\n    'aria-valuemax', state.max\n  );\n\n  minThumb.setAttribute(\n    'aria-valuenow', state.min\n  );\n\n  minThumb.setAttribute(\n    'aria-valuetext', currency.format(state.min)\n  );\n\n  maxThumb.setAttribute(\n    'aria-valuemin', state.min\n  );\n\n  maxThumb.setAttribute(\n    'aria-valuemax', state.upperLimit\n  );\n\n  maxThumb.setAttribute(\n    'aria-valuenow', state.max\n  );\n\n  maxThumb.setAttribute(\n    'aria-valuetext', currency.format(state.max)\n  );\n\n  // 此处同步视觉位置及价格输入框\n}\n\nfunction onKeydown(event, type) {\n  const min = type === 'min'\n    ? state.lowerLimit\n    : state.min;\n\n  const max = type === 'min'\n    ? state.max\n    : state.upperLimit;\n\n  let value = state[type];\n\n  switch (event.key) {\n    case 'ArrowRight':\n    case 'ArrowUp':\n      value += state.step;\n      break;\n\n    case 'ArrowLeft':\n    case 'ArrowDown':\n      value -= state.step;\n      break;\n\n    case 'Home':\n      value = min;\n      break;\n\n    case 'End':\n      value = max;\n      break;\n\n    default:\n      return;\n  }\n\n  event.preventDefault();\n\n  setPrice(type, value);\n}\n\nminThumb.addEventListener('keydown', event => {\n  onKeydown(event, 'min');\n});\n\nmaxThumb.addEventListener('keydown', event => {\n  onKeydown(event, 'max');\n});\n\nrender();\n```\n\n以上仅实现键盘操作和 ARIA 数值约束，尚未包含指针拖拽、触屏、轨道点击、视觉位置计算等完整功能。\n\n正式项目建议优先使用原生 Range Input 或经过充分无障碍验证的组件库，并提供两个可直接输入价格的字段作为替代操作。\n\n### 6.6 Shopify 价格参数\n\nShopify 原生筛选通常使用：\n\n```text\nfilter.v.price.gte=20\nfilter.v.price.lte=150\n```\n\n不过在 Liquid 中，仍然应该优先使用：\n\n```liquid\n{{ filter.min_value.param_name }}\n{{ filter.max_value.param_name }}\n```\n\n特别注意，Liquid 中的价格数值与 URL 中用户输入的货币金额不能不加区分地直接使用。\n\n正式项目需要正确处理当前币种、金额单位、小数分隔符以及区域格式。\n\n---\n\n## 7. Active Filters：已选筛选条件\n\nActive Filters 通常以 Chip 或 Tag 的形式展示。\n\n");
