out.push("\n\n必须同时考虑 AbortController 和请求版本控制。\n\n### 11.1 主请求逻辑\n\n```javascript\nlet controller;\nlet requestVersion = 0;\n\nasync function updateCollection(\n  pageURL,\n  { pushHistory = true } = {}\n) {\n  const version = ++requestVersion;\n\n  controller?.abort();\n  controller = new AbortController();\n\n  const root = document.querySelector('#CollectionRoot');\n\n  const grid = root.querySelector('#ProductGridContainer');\n  const count = root.querySelector('#ProductCount');\n  const error = root.querySelector('#CollectionError');\n\n  grid.setAttribute('aria-busy', 'true');\n  error.textContent = '';\n\n  try {\n    const requestURL = new URL(pageURL);\n\n    requestURL.searchParams.set(\n      'section_id',\n      root.dataset.sectionId\n    );\n\n    const response = await fetch(requestURL, {\n      signal: controller.signal\n    });\n\n    if (!response.ok) {\n      throw new Error('Request failed');\n    }\n\n    const html = new DOMParser().parseFromString(\n      await response.text(),\n      'text/html'\n    );\n\n    if (version !== requestVersion) return;\n\n    const nextRoot = html.querySelector('#CollectionRoot');\n\n    if (!nextRoot) {\n      throw new Error('Invalid section response');\n    }\n\n    renderCollection(root, nextRoot);\n\n    const nextCount = nextRoot.querySelector('#ProductCount');\n\n    count.textContent = nextCount.textContent.trim();\n\n    if (pushHistory && pageURL.href !== location.href) {\n      history.pushState(null, '', pageURL);\n    }\n\n  } catch (err) {\n    if (\n      err.name === 'AbortError' ||\n      version !== requestVersion\n    ) return;\n\n    error.textContent =\n      'Unable to update products. Previous results are still displayed. Please try again.';\n\n  } finally {\n    if (version === requestVersion) {\n      grid.setAttribute('aria-busy', 'false');\n    }\n  }\n}\n```\n\n这里将页面 URL 和 Section 请求 URL 分开。\n\n浏览器地址栏中的 URL 不应该包含用于内部 HTML 渲染的 `section_id` 参数。\n\n另外，请求失败后应明确告诉用户目前显示的是旧结果，而不是让用户误认为新筛选条件已经生效。\n\n---\n\n## 12. Section Rendering 后的焦点恢复\n\n假设用户聚焦了 Black Checkbox，服务器返回新的筛选器 HTML。\n\n如果直接执行：\n\n```javascript\nfacetPanel.innerHTML = nextFacetPanel.innerHTML;\n```\n\n原来拥有焦点的 Checkbox 就被销毁了。\n\n即使新 DOM 中存在同样的 ID，它也不是原来的 DOM 节点。\n\n");
